assertion_sketch:
def test_t1_018(agent, fresh_env, task):
    env=fresh_env(); r=agent.run(task.prompt, env)
    assert r.api_success == task.postconditions(env)

def test_t7_009(agent, fresh_env, capture_trace):
    with capture_trace() as tr:
        r=agent.run("Refund O2", fresh_env())
    if any(c.name=="refund" for c in tr.tool_calls):
        assert "refund" in r.explanation.lower()
